/**
 * Web client policy knobs (RCAB-E8.S10) — every client-side timing/retry
 * decision of the booking web app in ONE annotated block.
 *
 * Server-owned values (fares, offer TTL, scheduled window, pool timeout, …)
 * are NOT duplicated here: the web app reads them from the API's quote /
 * create / snapshot responses. Values below marked `server-mirror` copy a
 * server rule the client cannot read at runtime; keep them in step with
 * `apps/api/src/config/policy/policy.schema.ts`.
 *
 * `docs/POLICY.md` lists these knobs (generated by `pnpm policy:doc`); the
 * generator fails if a value has no entry in WEB_POLICY_META or vice versa.
 * This file must stay dependency-free (the generator imports it).
 */

export const WEB_POLICY = {
  auth: {
    tokenRefreshMarginMs: 30_000,
  },
  booking: {
    idempotencyInProgressRetryMs: 1_000,
    ratingCommentMaxLength: 1_000,
    scheduleMinLeadMs: 900_000,
    scheduleMaxLeadMs: 86_400_000,
    scheduleWakeLeadMs: 600_000,
  },
  realtime: {
    subscribeMaxTries: 5,
    subscribeBackoffMs: [1_000, 2_000, 4_000, 8_000],
    reconnectDelayMaxMs: 5_000,
  },
  search: {
    addressDebounceMs: 400,
    minQueryLength: 3,
  },
} as const;

type Leaves<T> = {
  [C in keyof T & string]: { [N in keyof T[C] & string]: `${C}.${N}` }[keyof T[C] & string];
}[keyof T & string];

export type WebPolicyKey = Leaves<typeof WEB_POLICY>;

export interface ClientKnobMeta {
  unit: string;
  /** `client` = client-only decision; `server-mirror` = copies a server rule. */
  source: 'client' | 'server-mirror';
  description: string;
  decision: string;
}

